import { DatabaseContext, DbClient, RunContext } from 'vlquery';
import { DatabaseConnection } from './database-connection';

/**
 * Constructor of a context generated by `acryps-local create-context`
 */
export type DatabaseContextConstructor<TContext extends DatabaseContext> = new (client: DbClient, runContext?: RunContext) => TContext;

/**
 * Configuration of a database distributed over multiple locations
 */
export type DatabaseConfiguration<TContext extends DatabaseContext> = {
	/**
	 * Context generated by `acryps-local create-context`, all databases share the same schema
	 */
	context: DatabaseContextConstructor<TContext>;

	/**
	 * Database at the current location, connected all the time
	 */
	local: DatabaseConnection;

	/**
	 * Databases at other locations, only connected on demand
	 */
	remotes?: DatabaseConnection[];

	runContext?: RunContext;

	/**
	 * Milliseconds a remote connection stays open after its last use
	 * @default 60000
	 */
	remoteIdleTimeout?: number;
}
